"""
Interfaces for dependency injection to reduce coupling.

This module defines minimal interfaces (abstractions) for core dependencies
so that concrete implementations (Database, Config) can be passed at runtime
instead of being imported as singletons. This improves testability and
maintainability by enabling mocking and reducing ripple effects across modules.
"""
from typing import Dict, List, Optional

from .models import Coin, Pair


class ConfigInterface:
    """Interface for configuration access."""

    @property
    def BRIDGE_SYMBOL(self) -> str:
        """Bridge symbol (e.g., "USDT")."""
        raise NotImplementedError

    @property
    def BRIDGE(self) -> 'Coin':
        """Bridge coin object."""
        raise NotImplementedError

    @property
    def TESTNET(self) -> bool:
        """Whether running on testnet."""
        raise NotImplementedError

    @property
    def SCOUT_HISTORY_PRUNE_TIME(self) -> float:
        """Hours to keep scout history."""
        raise NotImplementedError

    @property
    def SCOUT_MULTIPLIER(self) -> float:
        """Scout multiplier."""
        raise NotImplementedError

    @property
    def SCOUT_SLEEP_TIME(self) -> int:
        """Seconds to sleep between scout cycles."""
        raise NotImplementedError

    @property
    def BINANCE_API_KEY(self) -> str:
        """Binance API key."""
        raise NotImplementedError

    @property
    def BINANCE_API_SECRET_KEY(self) -> str:
        """Binance API secret key."""
        raise NotImplementedError

    @property
    def BINANCE_TLD(self) -> str:
        """Binance TLD (e.g., 'com')."""
        raise NotImplementedError

    @property
    def SUPPORTED_COIN_LIST(self) -> List[str]:
        """List of supported coin symbols."""
        raise NotImplementedError

    @property
    def CURRENT_COIN_SYMBOL(self) -> Optional[str]:
        """Current coin symbol if specified."""
        raise NotImplementedError

    @property
    def STRATEGY(self) -> str:
        """Current strategy name."""
        raise NotImplementedError

    @property
    def SELL_TIMEOUT(self) -> str:
        """Sell timeout setting."""
        raise NotImplementedError

    @property
    def BUY_TIMEOUT(self) -> str:
        """Buy timeout setting."""
        raise NotImplementedError

    @property
    def USE_MARGIN(self) -> str:
        """Whether to use margin."""
        raise NotImplementedError

    @property
    def SCOUT_MARGIN(self) -> float:
        """Scout margin percentage."""
        raise NotImplementedError


class DatabaseInterface:
    """Interface for database operations."""

    def set_coins(self, symbols: List[str]) -> None:
        """Set supported coins and create pairs."""
        raise NotImplementedError

    def get_coins(self, only_enabled: bool = True) -> List[Coin]:
        """Get list of coins."""
        raise NotImplementedError

    def get_coin(self, coin) -> Coin:
        """Get coin by symbol or Coin object."""
        raise NotImplementedError

    def set_current_coin(self, coin) -> None:
        """Set the currently held coin."""
        raise NotImplementedError

    def get_current_coin(self) -> Optional[Coin]:
        """Get the currently held coin."""
        raise NotImplementedError

    def get_pair(self, from_coin, to_coin) -> Optional[Pair]:
        """Get pair between two coins."""
        raise NotImplementedError

    def get_pairs_from(self, from_coin, only_enabled: bool = True) -> List[Pair]:
        """Get pairs originating from a coin."""
        raise NotImplementedError

    def log_scout(
        self,
        pair: Pair,
        target_ratio: float,
        current_coin_price: float,
        other_coin_price: float,
    ) -> None:
        """Log a scout operation."""
        raise NotImplementedError

    def prune_scout_history(self) -> None:
        """Prune old scout history."""
        raise NotImplementedError

    def prune_value_history(self) -> None:
        """Prune old value history."""
        raise NotImplementedError

    def create_database(self) -> None:
        """Create database schema."""
        raise NotImplementedError

    def migrate_old_state(self) -> None:
        """Migrate old state from file to database."""
        raise NotImplementedError

    def start_trade_log(self, from_coin: Coin, to_coin: Coin, selling: bool):
        """Start logging a trade."""
        raise NotImplementedError

    def send_update(self, model) -> None:
        """Send update notification."""
        raise NotImplementedError


class BinanceAPIManagerInterface:
    """Interface for Binance API operations."""

    def get_ticker_price(self, ticker_symbol: str) -> Optional[float]:
        """Get ticker price for a symbol."""
        raise NotImplementedError

    def get_currency_balance(self, currency_symbol: str, force: bool = False) -> float:
        """Get balance of a specific coin."""
        raise NotImplementedError

    def get_fee(self, origin_coin: Coin, target_coin: Coin, selling: bool) -> float:
        """Get trade fee for a pair."""
        raise NotImplementedError

    def get_min_notional(self, origin_symbol: str, target_symbol: str) -> float:
        """Get minimum notional value for a trade."""
        raise NotImplementedError

    def buy_alt(self, origin_coin: Coin, target_coin: Coin):
        """Buy altcoin."""
        raise NotImplementedError

    def sell_alt(self, origin_coin: Coin, target_coin: Coin):
        """Sell altcoin."""
        raise NotImplementedError

    def collate_coins(self, target_symbol: str) -> float:
        """Calculate total value in terms of target symbol."""
        raise NotImplementedError
